import {SPECIES} from './simulation.js';
import {seedRandom} from './genetics.js';
export class Soundscape{
 constructor(){this.enabled=false;this.ctx=null;this.voices=0;this.nextCall=0;}
 async toggle(){if(!this.ctx){const AC=window.AudioContext||window.webkitAudioContext;this.ctx=new AC();this.master=this.ctx.createGain();this.master.gain.value=0;const compressor=this.ctx.createDynamicsCompressor();compressor.threshold.value=-20;compressor.ratio.value=5;this.master.connect(compressor);compressor.connect(this.ctx.destination);for(const [i,f] of [130.81,196,261.63].entries()){const osc=this.ctx.createOscillator(),gain=this.ctx.createGain();osc.type='sine';osc.frequency.value=f;gain.gain.value=.015/(i+1);osc.connect(gain);gain.connect(this.master);osc.start();}}
 this.enabled=!this.enabled;await this.ctx.resume();this.master.gain.setTargetAtTime(this.enabled?.38:0,this.ctx.currentTime,.6);return this.enabled;}
 note(freq,duration,pan,type='sine',end=freq,gain=.13,delay=0){if(!this.enabled||this.voices>=6||this.ctx.state!=='running')return;this.voices++;const ctx=this.ctx,at=ctx.currentTime+delay,osc=ctx.createOscillator(),amp=ctx.createGain(),filter=ctx.createBiquadFilter(),stereo=ctx.createStereoPanner();osc.type=type;osc.frequency.setValueAtTime(Math.max(35,freq),at);osc.frequency.exponentialRampToValueAtTime(Math.max(35,end),at+duration);filter.type='lowpass';filter.frequency.value=type==='sawtooth'?380:1800;amp.gain.setValueAtTime(.0001,at);amp.gain.exponentialRampToValueAtTime(gain,at+.035);amp.gain.exponentialRampToValueAtTime(.0001,at+duration);stereo.pan.value=Math.max(-1,Math.min(1,pan));osc.connect(filter);filter.connect(amp);amp.connect(stereo);stereo.connect(this.master);osc.start(at);osc.stop(at+duration+.04);osc.onended=()=>{osc.disconnect();filter.disconnect();amp.disconnect();stereo.disconnect();this.voices--;};}
 call(c,center=0,volume=1){if(!c||!this.enabled)return;const s=SPECIES[c.species],rand=seedRandom(c.dna.seed),pitch=s.call*(.84+rand()*.32)*(c.sex==='F'?1.13:1)*(c.age<3?1.3:1),pan=(c.x-center)/22;
 if(s.id===3){this.note(pitch,.65,pan,'sawtooth',pitch*.60,.14*volume);return;}if(s.id===5){this.note(pitch,.18,pan,'sine',pitch*1.65,.10*volume);this.note(pitch*1.4,.19,pan,'sine',pitch*.65,.08*volume,.22);return;}if(s.id===1){this.note(pitch,.55,pan,'triangle',pitch*.72,.10*volume);return;}const count=s.id===4?3:2;for(let i=0;i<count;i++)this.note(pitch*(1+i*.12),.15+rand()*.10,pan,s.id===2?'sine':'triangle',pitch*(i%2?.8:1.35),.09*volume,i*.21);}
 event(e,sim){if(!this.enabled)return;if(e.kind==='birth'){this.note(660,.24,0,'sine',880,.09);this.note(880,.3,0,'sine',990,.07,.22);}if(e.kind==='death')this.note(230,.7,0,'sine',115,.08);if(e.kind==='court')this.call(sim.byId.get(e.entity));}
 update(now,sim,center){if(!this.enabled||now<this.nextCall||!sim.creatures.length)return;this.nextCall=now+4500+Math.random()*4500;const c=sim.creatures[Math.floor(Math.random()*sim.creatures.length)];this.call(c,center,.65);}
 visibility(hidden){if(!this.ctx)return;if(hidden)this.ctx.suspend();else if(this.enabled)this.ctx.resume();}
}
